-- Name: apply_tenancy(); Type: FUNCTION; Schema: kv_admin; Owner: -
--

CREATE FUNCTION kv_admin.apply_tenancy() RETURNS void
    LANGUAGE plpgsql
    AS $$
        DECLARE
            r record;
        BEGIN
            FOR r IN
                SELECT c.table_schema, c.table_name
                FROM information_schema.columns c
                JOIN information_schema.tables t
                  ON t.table_schema = c.table_schema AND t.table_name = c.table_name
                WHERE c.column_name = 'tenant_id'
                  AND t.table_type = 'BASE TABLE'
                  AND c.table_schema IN ('kv_admin','kv_media','kv_social','kv_ai','kv_studio','kv_commerce','kv_ledger','kv_tax','kv_trust')
                  AND NOT (c.table_schema = 'kv_admin' AND c.table_name NOT IN ('audit_log','impersonation_sessions'))
                  AND NOT (c.table_schema = 'kv_commerce' AND c.table_name = 'provider_events')
                  AND NOT (c.table_schema = 'kv_ai' AND c.table_name = 'llm_calls')
            LOOP
                EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.table_schema, r.table_name);
                EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I.%I', r.table_schema, r.table_name);
                EXECUTE format(
                    'CREATE POLICY tenant_isolation ON %I.%I '
                    'USING (tenant_id = kv_admin.current_tenant() OR kv_admin.is_platform()) '
                    'WITH CHECK (tenant_id = kv_admin.current_tenant() OR kv_admin.is_platform())',
                    r.table_schema, r.table_name);
            END LOOP;
            EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA kv_admin, kv_media, kv_social, kv_ai, kv_studio, kv_commerce, kv_ledger, kv_tax, kv_trust TO klygenix_video_app';
            EXECUTE 'GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA kv_admin, kv_media, kv_social, kv_ai, kv_studio, kv_commerce, kv_ledger, kv_tax, kv_trust TO klygenix_video_app';
            EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON kv_ledger.journals, kv_ledger.journal_lines FROM klygenix_video_app';
            EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON kv_admin.audit_log FROM klygenix_video_app';
            EXECUTE 'REVOKE DELETE, TRUNCATE ON kv_commerce.provider_events FROM klygenix_video_app';
        END
        $$;


