--

CREATE TABLE kv_media.videos (
    id bigint NOT NULL,
    tenant_id integer NOT NULL,
    channel_id bigint NOT NULL,
    uploader_user_id integer,
    public_id character varying(16) NOT NULL,
    title character varying(200) NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    language character varying(8) DEFAULT 'en'::character varying NOT NULL,
    kind character varying(8) NOT NULL,
    source character varying(8) NOT NULL,
    status character varying(12) NOT NULL,
    status_note text,
    visibility character varying(10) NOT NULL,
    publish_at timestamp with time zone,
    published_at timestamp with time zone,
    duration_ms bigint DEFAULT '0'::bigint NOT NULL,
    width integer,
    height integer,
    provider character varying(12),
    provider_video_id character varying(80),
    source_key character varying(300),
    thumbnail_key character varying(300),
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    ai_generated boolean DEFAULT false NOT NULL,
    rights_declared boolean DEFAULT false NOT NULL,
    rights_note text,
    source_clip_id bigint,
    embed_platform character varying(12),
    embed_external_id character varying(80),
    embed_url character varying(500),
    embed_owner_verified boolean DEFAULT false NOT NULL,
    ai_status character varying(12) DEFAULT 'pending'::character varying NOT NULL,
    view_count bigint DEFAULT '0'::bigint NOT NULL,
    like_count bigint DEFAULT '0'::bigint NOT NULL,
    comment_count bigint DEFAULT '0'::bigint NOT NULL,
    danmaku_count bigint DEFAULT '0'::bigint NOT NULL,
    watch_ms bigint DEFAULT '0'::bigint NOT NULL,
    completions bigint DEFAULT '0'::bigint NOT NULL,
    search tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, (((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(description, ''::text)))) STORED,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    thumbnail_ideas jsonb DEFAULT '[]'::jsonb NOT NULL,
    access character varying(8) DEFAULT 'free'::character varying NOT NULL,
    price_inr_minor integer,
    members_rank smallint,
    preview_seconds integer DEFAULT 60 NOT NULL,
    dubbing_allowed boolean DEFAULT false NOT NULL,
    ads_enabled boolean DEFAULT true NOT NULL,
    sponsor_deal_id bigint,
    made_for_kids boolean DEFAULT false NOT NULL,
    safety_labels jsonb,
    roman text DEFAULT ''::text NOT NULL,
    search_roman tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, roman)) STORED,
    thumbnail_ai boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_videos_access CHECK (((access)::text = ANY ((ARRAY['free'::character varying, 'members'::character varying, 'paid'::character varying])::text[]))),
    CONSTRAINT ck_videos_kind CHECK (((kind)::text = ANY ((ARRAY['long'::character varying, 'reel'::character varying])::text[]))),
    CONSTRAINT ck_videos_paid_price CHECK ((((access)::text <> 'paid'::text) OR (price_inr_minor > 0))),
    CONSTRAINT ck_videos_source CHECK (((source)::text = ANY ((ARRAY['upload'::character varying, 'clip'::character varying, 'embed'::character varying])::text[]))),
    CONSTRAINT ck_videos_status CHECK (((status)::text = ANY ((ARRAY['uploading'::character varying, 'processing'::character varying, 'scanning'::character varying, 'in_review'::character varying, 'published'::character varying, 'blocked'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT ck_videos_visibility CHECK (((visibility)::text = ANY ((ARRAY['public'::character varying, 'unlisted'::character varying, 'private'::character varying, 'scheduled'::character varying])::text[])))
);


